+/* Header */
+.site-header{
+  position:sticky;top:0;z-index:40;
+  background: linear-gradient(to bottom, rgba(0,0,0,.88), rgba(0,0,0,.50));
+  backdrop-filter: blur(10px);
+  border-bottom: 1px solid rgba(255,255,255,.06);
+}
+.header-inner{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:14px 0}
+.brand{
+  display:flex;align-items:center;gap:10px;font-weight:800;letter-spacing:.2px
+}
+.brand-mark{
+  width:18px;height:18px;border-radius:6px;
+  background: linear-gradient(135deg, var(--accent), #ff5b5b);
+  box-shadow: 0 12px 28px rgba(229,9,20,.28);
+}
+.brand-name{font-size:18px}
+.header-actions{display:flex;align-items:center;gap:10px}
+.lang{
+  appearance:none;
+  color:var(--text);
+  background: rgba(0,0,0,.55);
+  border:1px solid rgba(255,255,255,.16);
+  padding:10px 12px;
+  border-radius: 12px;
+}
+
+/* Buttons */
+.btn{
+  border:1px solid rgba(255,255,255,.14);
+  background: rgba(255,255,255,.06);
+  color:var(--text);
+  padding:10px 14px;
+  border-radius: 12px;
+  cursor:pointer;
+  transition: transform .12s ease, background .12s ease, border-color .12s ease;
+}
+.btn:hover{transform: translateY(-1px);background: rgba(255,255,255,.10);border-color: rgba(255,255,255,.20)}
+.btn:active{transform: translateY(0)}
+.btn-primary{
+  background: linear-gradient(135deg, var(--accent), var(--accent-2));
+  border-color: rgba(255,255,255,.10);
+  box-shadow: 0 18px 45px rgba(229,9,20,.28);
+}
+.btn-primary:hover{background: linear-gradient(135deg, #ff0f1b, #ff3a3a)}
+.btn-primary:focus-visible{outline:3px solid var(--focus);outline-offset:3px}
+.btn-ghost{background: transparent;border-color: rgba(255,255,255,.14)}
