+/* Hero */
+.hero{
+  position:relative;
+  overflow:hidden;
+  border-bottom: 1px solid rgba(255,255,255,.06);
+}
+.hero::before{
+  content:"";
+  position:absolute;inset:-120px -80px;
+  background:
+    linear-gradient(180deg, rgba(0,0,0,.25), rgba(0,0,0,.92) 70%),
+    radial-gradient(1200px 600px at 60% 0%, rgba(229,9,20,.25), transparent 60%),
+    url("assets/hero-mosaic.svg");
+  background-size: auto, auto, cover;
+  background-position: center, center, center;
+  filter: saturate(1.1) contrast(1.05);
+  transform: scale(1.04);
+}
+.hero-inner{position:relative;padding:62px 0 54px}
+
+.hero-grid{
+  display:grid;
+  grid-template-columns: 1.1fr .9fr;
+  gap: 24px;
+  align-items:center;
+}
+.hero h1{
+  margin:0;
+  font-weight: 900;
+  letter-spacing: -0.03em;
+  font-size: clamp(40px, 4.1vw, 68px);
+  line-height: 1.02;
+}
+.hero .sub{
+  margin:14px 0 0;
+  font-size: 18px;
+  color: var(--muted);
+}
+.hero .price{
+  margin:12px 0 0;
+  font-size: 18px;
+  color: rgba(255,255,255,.9);
+}
+.hero .prompt{margin:22px 0 12px;color: var(--muted)}
+
+.email-row{display:flex;gap:10px;align-items:stretch}
+.field{
+  flex:1;
+  min-width: 0;
+  border-radius: 14px;
+  border:1px solid rgba(255,255,255,.16);
+  background: rgba(0,0,0,.55);
+  color: var(--text);
+  padding: 13px 14px;
+  outline: none;
+}
+.field::placeholder{color: rgba(255,255,255,.55)}
+.field:focus{border-color: rgba(229,9,20,.55);box-shadow: 0 0 0 3px rgba(229,9,20,.20)}
+.hint{margin:10px 0 0;color: var(--muted-2);font-size: 13px}
+
+.hero-card{
+  background: linear-gradient(180deg, rgba(20,20,20,.92), rgba(0,0,0,.70));
+  border: 1px solid rgba(255,255,255,.10);
+  border-radius: var(--radius);
+  box-shadow: 0 30px 80px rgba(0,0,0,.55);
+  padding: 18px;
+}
+.stat-row{display:grid;grid-template-columns: 1fr 1fr;gap:10px;margin-top:8px}
+.stat{
+  border-radius: 14px;
+  padding: 14px;
+  background: rgba(255,255,255,.06);
+  border: 1px solid rgba(255,255,255,.10);
+}
+.stat .k{font-size: 12px;letter-spacing:.14em;text-transform:uppercase;color: rgba(255,255,255,.62)}
+.stat .v{margin-top:6px;font-size: 18px;font-weight: 800}
+.hero-pill{
+  display:inline-flex;align-items:center;gap:10px;
+  padding:10px 12px;border-radius:999px;
+  background: rgba(229,9,20,.12);
+  border: 1px solid rgba(229,9,20,.35);
+  color: rgba(255,255,255,.92);
+  font-weight: 650;
+}
+.pulse{
+  width:8px;height:8px;border-radius:50%;background: var(--accent);
+  box-shadow: 0 0 0 0 rgba(229,9,20,.6);
+  animation: pulse 2s infinite;
+}
+@keyframes pulse{
+  0%{box-shadow:0 0 0 0 rgba(229,9,20,.55)}
+  70%{box-shadow:0 0 0 12px rgba(229,9,20,0)}
+  100%{box-shadow:0 0 0 0 rgba(229,9,20,0)}
+}
+
+/* Sections */
+.section{padding:44px 0}
+.section-title{margin:0 0 18px;font-size: 28px;font-weight: 900;letter-spacing:-.02em}
+.section-note{margin:0 0 16px;color: var(--muted)}
+
+/* Trending carousel */
+.carousel{
+  position:relative;
+}
+.carousel-track{
+  display:flex;
+  gap: 14px;
+  overflow:auto;
+  scroll-snap-type: x mandatory;
+  padding: 6px 2px 12px;
+  scrollbar-width: none;
+}
+.carousel-track::-webkit-scrollbar{display:none}
+.tile{
+  position:relative;
+  flex: 0 0 auto;
+  width: 190px;
+  height: 260px;
+  border-radius: 18px;
+  overflow:hidden;
+  border: 1px solid rgba(255,255,255,.10);
+  background: radial-gradient(220px 260px at 30% 10%, rgba(229,9,20,.22), transparent 60%),
+              linear-gradient(180deg, rgba(255,255,255,.05), rgba(0,0,0,.55));
+  box-shadow: 0 22px 60px rgba(0,0,0,.55);
+  scroll-snap-align: start;
+}
+.tile::before{
+  content:"";
+  position:absolute;inset:0;
+  background:
+    linear-gradient(180deg, rgba(0,0,0,.0), rgba(0,0,0,.68) 78%),
+    url("assets/poster-placeholder.svg");
+  background-size: cover;
+  background-position: center;
+  opacity: .95;
+  filter: contrast(1.1) saturate(1.05);
+}
+.rank{
+  position:absolute;left:-10px;bottom:-32px;
+  font-size: 140px;
+  line-height: 1;
+  font-weight: 950;
+  color: rgba(255,255,255,.12);
+  letter-spacing: -0.04em;
+  text-shadow: 0 18px 60px rgba(0,0,0,.55);
+}
+.tile-inner{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:flex-end;padding:14px}
+.badge{
+  align-self:flex-start;
+  font-size: 12px;
+  letter-spacing:.12em;
+  text-transform: uppercase;
+  color: rgba(255,255,255,.82);
+  background: rgba(0,0,0,.55);
+  border: 1px solid rgba(255,255,255,.14);
+  padding: 7px 10px;
+  border-radius: 999px;
+}
+.title{
+  margin-top:10px;
+  font-size: 18px;
+  font-weight: 850;
+  letter-spacing: -.02em;
+}
+.tile:hover{transform: translateY(-2px)}
+.tile{transition: transform .14s ease}
+
+.carousel-nav{
+  display:flex;gap:10px;justify-content:flex-end;align-items:center;margin-top:12px
+}
+.icon-btn{
+  width:44px;height:44px;
+  border-radius: 14px;
+  border: 1px solid rgba(255,255,255,.14);
+  background: rgba(255,255,255,.06);
+  color: var(--text);
+  cursor:pointer;
+  display:grid;place-items:center;
+  transition: transform .12s ease, background .12s ease;
+}
+.icon-btn:hover{transform: translateY(-1px);background: rgba(255,255,255,.10)}
+.icon-btn:focus-visible{outline:3px solid var(--focus);outline-offset:3px}
+
+/* Feature cards */
+.features{
+  display:grid;
+  grid-template-columns: repeat(4, minmax(0, 1fr));
+  gap: 14px;
+}
+.card{
+  position:relative;
+  background: linear-gradient(180deg, rgba(20,20,20,.96), rgba(0,0,0,.65));
+  border: 1px solid rgba(255,255,255,.10);
+  border-radius: var(--radius);
+  padding: 18px;
+  min-height: 190px;
+  box-shadow: 0 24px 70px rgba(0,0,0,.45);
+}
+.card h3{margin:0;font-size: 18px;font-weight: 900;letter-spacing:-.02em}
+.card p{margin:10px 0 0;color: var(--muted)}
+.card .corner{
+  position:absolute;right:14px;bottom:14px;
+  width:38px;height:38px;border-radius: 14px;
+  background: rgba(229,9,20,.16);
+  border: 1px solid rgba(229,9,20,.30);
+  display:grid;place-items:center;
+}
+
+/* FAQ */
+.faq{
+  display:grid;
+  gap: 10px;
+}
+.faq-item{
+  border-radius: var(--radius);
+  border: 1px solid rgba(255,255,255,.10);
+  background: rgba(20,20,20,.86);
+  overflow:hidden;
+}
+.faq-q{
+  width:100%;
+  text-align:left;
+  display:flex;align-items:center;justify-content:space-between;gap:10px;
+  padding: 18px;
+  background: transparent;
+  border: 0;
+  color: var(--text);
+  cursor:pointer;
+}
+.faq-q span{font-size: 18px;font-weight: 850}
+.chev{width:18px;height:18px;transition: transform .18s ease;opacity:.9}
+.faq-item[data-open="true"] .chev{transform: rotate(180deg)}
+.faq-a{
+  max-height: 0;
+  overflow: hidden;
+  transition: max-height .22s ease;
+  border-top: 1px solid rgba(255,255,255,.08);
+}
+.faq-a-inner{padding: 14px 18px 18px;color: var(--muted);font-size: 15px}
+
+/* CTA */
+.cta{
+  border-top: 1px solid rgba(255,255,255,.06);
+  border-bottom: 1px solid rgba(255,255,255,.06);
+  background: radial-gradient(800px 420px at 20% 20%, rgba(229,9,20,.22), transparent 60%),
+              rgba(20,20,20,.55);
+}
+.cta-inner{padding: 42px 0}
+.cta-box{
+  max-width: 820px;
+  margin: 0 auto;
+  text-align:center;
+}
+.cta-box .prompt{margin:0 0 14px;color: var(--muted);font-size: 16px}
+
+/* Footer */
+footer{padding: 36px 0 56px;color: rgba(255,255,255,.68)}
+.footer-top{margin-bottom: 18px}
+.footer-grid{
+  display:grid;
+  grid-template-columns: repeat(4, minmax(0, 1fr));
+  gap: 10px 18px;
+}
+.footer-grid a{display:block;padding:6px 0;color: rgba(255,255,255,.62)}
+.footer-grid a:hover{color: rgba(255,255,255,.9)}
+.footer-bottom{margin-top: 22px;display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}
+.legal{max-width: 720px;font-size: 12px;color: rgba(255,255,255,.52)}
+
+/* Login */
+.auth-wrap{min-height: calc(100vh - 70px);display:grid;place-items:center;padding: 34px 0}
+.auth-card{
+  width: min(520px, 100%);
+  background: linear-gradient(180deg, rgba(20,20,20,.92), rgba(0,0,0,.72));
+  border: 1px solid rgba(255,255,255,.10);
+  border-radius: 20px;
+  padding: 22px;
+  box-shadow: 0 40px 120px rgba(0,0,0,.6);
+}
+.auth-card h1{margin:0;font-size: 28px;font-weight: 950;letter-spacing:-.02em}
+.auth-card .sub{margin:8px 0 0;color: var(--muted)}
+.form{margin-top: 18px;display:grid;gap: 12px}
+.label{font-size: 13px;color: rgba(255,255,255,.72);letter-spacing:.02em}
+.stack{display:grid;gap:8px}
+.error{display:none;color: rgba(255,140,140,.92);font-size: 13px}
+.field[aria-invalid="true"]{border-color: rgba(255,100,100,.55);box-shadow: 0 0 0 3px rgba(255,90,90,.18)}
+.help-toggle{margin-top: 10px}
+.help-btn{padding: 0;border:0;background:transparent;color: rgba(255,255,255,.78);cursor:pointer;text-decoration: underline;text-decoration-color: rgba(255,255,255,.28)}
+.help-panel{
+  max-height:0;overflow:hidden;transition: max-height .22s ease;border-left: 2px solid rgba(229,9,20,.45);
+}
+.help-panel-inner{padding: 12px 0 0 14px;color: rgba(255,255,255,.66);font-size: 14px}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero-grid{grid-template-columns: 1fr;}
+  .hero-card{order:2}
+  .features{grid-template-columns: 1fr 1fr}
+  .footer-grid{grid-template-columns: 1fr 1fr}
+}
+@media (max-width: 560px){
+  .header-inner{padding: 12px 0}
+  .lang{display:none}
+  .email-row{flex-direction: column}
+  .tile{width: 160px;height: 230px}
+  .rank{font-size: 120px;left:-8px;bottom:-28px}
+  .features{grid-template-columns: 1fr}
+  .footer-grid{grid-template-columns: 1fr}
+}
+
+@media (prefers-reduced-motion: reduce){
+  *{scroll-behavior:auto !important}
+  .pulse{animation:none}
+  .faq-a,.help-panel,.chev,.btn,.tile,.icon-btn{transition:none}
+}
+
*** End Patch
PATCH

